/**
 * 剧情进度镜像（与 story_get_state payload 同形），供 Event Page 解析与 requirements 判定。
 */
import type { StoryEventLike, StoryEventPageContext } from './story-event-page-resolver';

export type StoryProgressSnapshot = {
  localCompletedEventIds: ReadonlySet<string>;
  serverCompletedEventIds: ReadonlySet<string>;
  battleClearedEventIds: ReadonlySet<string>;
  acceptedTaskIds: ReadonlySet<number>;
  completedTaskIds: ReadonlySet<number>;
  activeTasks: ReadonlyArray<{ taskId: number; status?: string }>;
  mainlineStep: number;
};

export function evaluateStoryRequirements(
  reqs: unknown[] | undefined,
  progress: StoryProgressSnapshot,
  isEventIdComplete: (eventId: string) => boolean,
): boolean {
  if (!reqs?.length) return true;
  for (const raw of reqs) {
    const req = raw as Record<string, unknown>;
    const rtype = String(req.type ?? req.action ?? '');
    if (rtype === 'event_done' || rtype === 'event_completed') {
      const eid = String(req.eventId ?? '');
      if (eid && !isEventIdComplete(eid)) return false;
    } else if (rtype === 'task_completed' || rtype === 'task_done') {
      const tid = Number(req.taskId ?? 0);
      if (!progress.completedTaskIds.has(tid)) return false;
    } else if (rtype === 'task_active' || rtype === 'task_accepted') {
      const tid = Number(req.taskId ?? 0);
      if (progress.completedTaskIds.has(tid)) return false;
      const active = progress.activeTasks.some((t) => Number(t.taskId) === tid);
      if (active || progress.acceptedTaskIds.has(tid)) continue;
      return false;
    } else if (rtype === 'task_not_started') {
      const tid = Number(req.taskId ?? 0);
      if (progress.completedTaskIds.has(tid)) return false;
      const active = progress.activeTasks.some((t) => Number(t.taskId) === tid);
      if (active) return false;
    } else if (rtype === 'task_failed') {
      return false;
    } else if (rtype === 'mainline_step') {
      const need = Number(req.value ?? 0);
      if (progress.mainlineStep < need) return false;
    } else if (rtype === 'story_var_equals' || rtype === 'var_equals') {
      return false;
    }
  }
  return true;
}

export function buildStoryEventPageContext(
  progress: StoryProgressSnapshot,
  deps: {
    stableEventId: (npcUid: string, ev: StoryEventLike) => string;
    isQuestStepComplete: (npcUid: string, ev: StoryEventLike) => boolean;
    isEventIdQuestStepComplete: (eventId: string) => boolean;
  },
): StoryEventPageContext {
  return {
    stableEventId: deps.stableEventId,
    isStepComplete: deps.isQuestStepComplete,
    requirementsMet: (reqs) =>
      evaluateStoryRequirements(reqs, progress, deps.isEventIdQuestStepComplete),
  };
}

export function isEventDoneInProgress(
  eventId: string,
  progress: StoryProgressSnapshot,
): boolean {
  return progress.localCompletedEventIds.has(eventId) || progress.serverCompletedEventIds.has(eventId);
}
